import * as T from 'three';
import {GLTFLoader} from './vendor/three/addons/loaders/GLTFLoader.js';
import {HDRLoader} from './vendor/three/addons/loaders/HDRLoader.js';
import {DRACOLoader} from './vendor/three/addons/loaders/DRACOLoader.js';
export {T};
export const vehicles={Sedan:{url:'/models/sedan.glb',name:'Mercedes-Benz S-Class',length:5.12,rotation:0},SUV:{url:'/models/suv.glb',name:'2021 Cadillac Escalade',length:5.38,rotation:0},Sprinter:{url:'/models/sprinter.glb',name:'Mercedes-Benz Sprinter',length:6.7,rotation:0}};
export async function studio(host){
 const renderer=new T.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,matchMedia('(max-width:760px)').matches?1.25:1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Interactive three-dimensional vehicle showroom');
 const scene=new T.Scene();scene.background=new T.Color('#0a0b0d');scene.fog=new T.Fog('#0a0b0d',19,50);const camera=new T.PerspectiveCamera(34,1,.1,100);camera.position.set(8,3.2,10);camera.lookAt(0,1,0);
 const pmrem=new T.PMREMGenerator(renderer);const hdr=await new HDRLoader().loadAsync('/models/studio.hdr');scene.environment=pmrem.fromEquirectangular(hdr).texture;hdr.dispose();pmrem.dispose();scene.environmentIntensity=.75;
 scene.add(new T.HemisphereLight(0xc4d4e5,0x14110d,.6));
 for(const [x,y,z,power,size] of [[-4,8,3,170,7],[5,5,-4,110,5],[-6,3,-5,60,4]]){const light=new T.SpotLight(0xffffff,power,40,Math.PI/3,.85,2);light.position.set(x,y,z);light.target.position.set(0,0,0);light.castShadow=power===170;const shadowSize=matchMedia('(max-width:760px)').matches?1024:2048;light.shadow.mapSize.set(shadowSize,shadowSize);light.shadow.bias=-.0002;light.shadow.normalBias=.025;light.shadow.radius=size;scene.add(light,light.target)}
 const floor=new T.Mesh(new T.PlaneGeometry(150,150),new T.MeshStandardMaterial({color:0x090a0c,roughness:.85,metalness:.05,envMapIntensity:.06}));floor.rotation.x=-Math.PI/2;floor.position.y=-.05;floor.receiveShadow=true;scene.add(floor);
 const resize=()=>{const {width,height}=host.getBoundingClientRect();renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix()};const observer=new ResizeObserver(resize);observer.observe(host);resize();
 return {renderer,scene,camera,floor,resize,dispose(){observer.disconnect();renderer.dispose();scene.environment.dispose()}};
}
export function platform(scene){const group=new T.Group();scene.add(group);const disc=new T.Mesh(new T.CylinderGeometry(4.05,4.09,.14,160),new T.MeshStandardMaterial({color:0x25282b,metalness:.35,roughness:.58,envMapIntensity:.15}));disc.position.y=.03;disc.receiveShadow=true;disc.castShadow=true;group.add(disc);const seam=new T.Mesh(new T.TorusGeometry(4.04,.009,8,192),new T.MeshStandardMaterial({color:0x66645c,metalness:.75,roughness:.35}));seam.rotation.x=Math.PI/2;seam.position.y=.105;group.add(seam);return group}
export async function loadVehicle(category){const spec=vehicles[category];const decoder=new DRACOLoader();decoder.setDecoderPath('/vendor/three/draco/');const loader=new GLTFLoader();loader.setDRACOLoader(decoder);const {scene:model}=await loader.loadAsync(spec.url);decoder.dispose();model.updateMatrixWorld(true);let box=new T.Box3().setFromObject(model),size=box.getSize(new T.Vector3());if(size.x>size.z)model.rotation.y=Math.PI/2;model.updateMatrixWorld(true);box=new T.Box3().setFromObject(model);size=box.getSize(new T.Vector3());model.scale.multiplyScalar(spec.length/size.z);model.rotation.y+=spec.rotation;model.updateMatrixWorld(true);box=new T.Box3().setFromObject(model);const center=box.getCenter(new T.Vector3());model.position.sub(new T.Vector3(center.x,box.min.y,center.z));model.traverse(o=>{if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;const materials=Array.isArray(o.material)?o.material:[o.material];for(let i=0;i<materials.length;i++){let m=materials[i];if(category==='Sprinter'){const name=m.name;if(/Glass/i.test(name)){m.color.set(0x101b21);m.metalness=.4;m.roughness=.12}else if(name==='Color_A10'){m.color.set(0x101112);m.roughness=.9;m.metalness=0}else if(name==='Color_A25'){m.color.set(0x7d8085);m.metalness=.9;m.roughness=.25}else{const paint=new T.MeshPhysicalMaterial({color:0x10141a,metalness:.35,roughness:.26,clearcoat:1,clearcoatRoughness:.1});paint.name=name;if(Array.isArray(o.material))o.material[i]=paint;else o.material=paint}continue}if(/carpaint|body.?paint|exterior.?paint|Radiant_Silver_Metallic/i.test(m.name)){const paint=new T.MeshPhysicalMaterial({color:0x101319,metalness:.62,roughness:.22,clearcoat:1,clearcoatRoughness:.1});paint.name=m.name;if(Array.isArray(o.material))o.material[i]=paint;else o.material=paint}else if(/tires|rubber/i.test(m.name)){m.color.set(0x101113);m.roughness=.83;m.metalness=0}else if(/headlight_glass/i.test(m.name)){m.opacity=.26;m.transparent=true;m.depthWrite=false}else{m.envMapIntensity=1.1}}});const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(64,64,12,64,64,64);gradient.addColorStop(0,'rgba(0,0,0,.72)');gradient.addColorStop(.6,'rgba(0,0,0,.48)');gradient.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);const contact=new T.Mesh(new T.PlaneGeometry(2.7,spec.length*.98),new T.MeshBasicMaterial({map:new T.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));contact.rotation.x=-Math.PI/2;contact.position.y=.004;const wrapper=new T.Group();wrapper.add(model,contact);return wrapper}

